/**
 * dev_scripts/patch-corridor-planner.mjs
 *
 * Frame Conn Patch Corridor Planner
 *
 * Uses the repository audit, symbol family tree, runtime composition data,
 * and effect atlas as a navigation substrate for change planning. It does
 * not edit source. It narrows a natural-language goal into the smallest
 * useful architectural corridor, then inspects only that corridor for
 * concrete file/symbol anchors.
 */

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import process from "node:process";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const SCRIPT_VERSION = "1.0.0";
const SCRIPT_FILE = fileURLToPath(import.meta.url);
const SCRIPT_DIRECTORY = path.dirname(SCRIPT_FILE);
const ROOT = path.resolve(SCRIPT_DIRECTORY, "..");

const STOP_WORDS = new Set([
  "a", "an", "and", "as", "at", "be", "by", "for", "from",
  "given", "in", "into", "is", "it", "of", "on", "or", "that",
  "the", "this", "through", "to", "up", "we", "with", "wire",
  "wiring", "make", "change", "patch", "frame", "conn"
]);

const args = process.argv.slice(2);
const goalIndex = args.indexOf("--goal");
const goal = goalIndex >= 0 ? String(args[goalIndex + 1] ?? "").trim() : args.filter(arg => !arg.startsWith("--")).join(" ').trim();
const outputIndex = args.indexOf("--output");
const outputFile = outputIndex >= 0
  ? path.resolve(ROOT, args[outputIndex + 1] ?? "patch-corridor-report.json")
  : path.join(ROOT, "patch-corridor-report.json");

if (!goal) {
  console.error("Usage: npm run patch-corridor -- --goal \"wire committed Scan through native execution\"");
  process.exit(2);
}

function normalize(value) {
  return String(value ?? "")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_.\/:-]+/g, " ')
    .toLowerCase();
}

function tokens(value) {
  return [...new Set(
    normalize(value)
      .split(/[^a-z0-9$]+/)
      .filter(token => token.length >= 3 && !STOP_WORDS.has(token))
  )];
}

const goalTokens = tokens(goal);

function runDiagnostic(scriptName, prefix) {
  const reportFile = path.join(os.tmpdir(), `${prefix}-${process.pid}-${Date.now()}.json`);
  const script = path.join(ROOT, "dev_scripts", scriptName);
  const result = spawnSync(process.execPath, [script, "--output", reportFile], {
    cwd: ROOT,
    encoding: "utf8"
  });
  if (result.status !== 0) {
    if (result.stdout) process.stdout.write(result.stdout);
    if (result.stderr) process.stderr.write(result.stderr);
    throw new Error(`${scriptName} failed; corridor planning requires healthy diagnostic data.`);
  }
  return JSON.parse(fs.readFileSync(reportFile, "utf8"));
}

function scoreText(value, weightedTokens = goalTokens) {
  const haystack = normalize(value);
  let score = 0;
  for (const token of weightedTokens) {
    if (haystack.includes(token)) score += token.length >= 7 ? 4 : 2;
  }
  return score;
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function familyGraphFromReports(symbolReport, repoReport) {
  const graph = new Map();
  const familyMap = new Map();
  const ensure = id => {
    if (!id) return null;
    if (!graph.has(id)) graph.set(id, new Set());
    return graph.get(id);
  };

  for (const family of asArray(symbolReport.families)) {
    familyMap.set(family.id, family);
    const edges = ensure(family.id);
    for (const target of [...asArray(family.incomingFamilies), ...asArray(family.outgoingFamilies)]) {
      edges.add(target);
      ensure(target)?.add(family.id);
    }
  }

  const flow = repoReport.dependencyFlow ?? repoReport.dependency_flow ?? {};
  const rivers = asArray(flow.rivers ?? flow.majorRivers);
  for (const river of rivers) {
    for (const stream of asArray(river.streams)) {
      const id = stream.id ?? stream.name;
      const edges = ensure(id);
      for (const target of [
        ...asArray(stream.upstream),
        ...asArray(stream.upstreamStreams),
        ...asArray(stream.downstream),
        ...asArray(stream.downstreamStreams)
      ]) {
        const targetId = typeof target === "string" ? target : target?.id;
        if (!targetId) continue;
        edges.add(targetId);
        ensure(targetId)?.add(id);
      }
    }
  }

  return { graph, familyMap, flow };
}

function familyScore(family, effectReport) {
  let score = scoreText(family.id) * 4;
  score += scoreText(asArray(family.locations).join(" "));
  for (const stem of asArray(family.topStems)) {
    score += scoreText(stem.stem) * Math.min(3, Number(stem.count ?? 1));
  }

  const endpointIntent = goalTokens.some(token => ["native", "lancer", "execute", "execution", "roll", "attack", "endpoint"].includes(token));
  if (endpointIntent && ["native-adapter", "action-execution", "execution-transaction", "system-bridge"].includes(family.id)) score += 8;

  const uiIntent = goalTokens.some(token => ["ui", "button", "committed", "presentation", "panel"].includes(token));
  if (uiIntent && family.id.startsWith("ui-")) score += 6;

  const owner = asArray(effectReport.ownerFamilies).find(item => item.id === family.id);
  if (owner && endpointIntent) score += Math.min(6, Number(owner.siteCount ?? 0) / 10);
  return score;
}

function shortestPath(graph, start, end) {
  if (start === end) return [start];
  const queue = [[start]];
  const seen = new Set([start]);
  while (queue.length) {
    const current = queue.shift();
    const tail = current[current.length - 1];
    for (const next of graph.get(tail) ?? []) {
      if (seen.has(next)) continue;
      const pathNow = [...current, next];
      if (next === end) return pathNow;
      seen.add(next);
      queue.push(pathNow);
    }
  }
  return [];
}

function deriveCorridor(graph, rankedFamilies) {
  const seeds = rankedFamilies.filter(item => item.score > 0).slice(0, 5).map(item => item.id);
  const selected = new Set(seeds);
  for (let i = 0; i < seeds.length; i += 1) {
    for (let j = i + 1; j < seeds.length; j += 1) {
      for (const id of shortestPath(graph, seeds[i], seeds[j]).slice(0, 8)) selected.add(id);
    }
  }
  for (const seed of seeds.slice(0, 3)) {
    for (const neighbor of graph.get(seed) ?? []) selected.add(neighbor);
  }
  return [...selected];
}

function topLevelSymbols(text) {
  const found = [];
  const patterns = [
    { kind: "function", regex: /^(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/gm },
    { kind: "class", regex: /^(?:export\s+)?class\s+([A-Za-z_$][\w$]*)/gm },
    { kind: "binding", regex: /^(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)/gm }
  ];
  for (const pattern of patterns) {
    let match;
    while ((match = pattern.regex.exec(text))) {
      found.push({
        name: match[1],
        kind: pattern.kind,
        line: text.slice(0, match.index).split("\n").length
      });
    }
  }
  return found;
}

function inspectCandidateFiles(corridorIds, familyMap, rankedFamilies) {
  const familyScores = new Map(rankedFamilies.map(item => [item.id, item.score]));
  const files = new Map();
  for (const id of corridorIds) {
    const family = familyMap.get(id);
    if (!family) continue;
    for (const relative of asArray(family.locations)) {
      const absolute = path.join(ROOT, relative);
      if (!fs.existsSync(absolute) || !fs.statSync(absolute).isFile()) continue;
      const text = fs.readFileSync(absolute, "utf8");
      const fileScore = (familyScores.get(id) ?? 0) + scoreText(relative) * 3 + scoreText(text.slice(0, 12000));
      const symbols = topLevelSymbols(text)
        .map(symbol => ({ ...symbol, score: scoreText(symbol.name) * 5 }))
        .filter(symbol => symbol.score > 0)
        .sort((a, b) => b.score - a.score || a.line - b.line)
        .slice(0, 10);
      files.set(relative, { file: relative, family: id, score: fileScore, symbols });
    }
  }
  return [...files.values()]
    .sort((a, b) => b.score - a.score || a.file.localeCompare(b.file))
    .slice(0, 14);
}

function runtimeConvergence(flow, corridor) {
  const rows = [];
  const rivers = asArray(flow.rivers ?? flow.majorRivers);
  for (const river of rivers) {
    const streams = asArray(river.streams).map(stream => stream.id ?? stream.name);
    if (!streams.some(stream => corridor.includes(stream))) continue;
    rows.push({
      river: river.name ?? river.id ?? "runtime",
      convergence: river.convergence ?? river.convergencePoint ?? null,
      outlet: river.outlet ?? null
    });
  }
  if (rows.length === 0) {
    rows.push({ river: "runtime", convergence: "scripts/feature-registry.js / styles/ui-registry.js", outlet: "scripts/runtime-orchestrator.js" });
  }
  return rows;
}

function effectBoundary(effectReport, corridor) {
  const owners = asArray(effectReport.ownerFamilies)
    .filter(owner => corridor.includes(owner.id))
    .sort((a, b) => Number(b.siteCount ?? 0) - Number(a.siteCount ?? 0));
  const endpointIntent = goalTokens.some(token => ["native", "lancer", "execute", "execution", "roll", "attack", "update", "mutate", "chat", "setting"].includes(token));
  if (!endpointIntent || owners.length === 0) return owners.slice(0, 4);
  return owners.slice(0, 6);
}

function confidence(candidateFiles, rankedFamilies) {
  const topFamily = rankedFamilies[0]?.score ?? 0;
  const second = rankedFamilies[1]?.score ?? 0;
  const symbolHits = candidateFiles.reduce((sum, file) => sum + file.symbols.length, 0);
  if (topFamily >= 18 && symbolHits >= 3 && topFamily >= second * 1.15) return "high";
  if (topFamily >= 8 && symbolHits >= 1) return "medium";
  return "exploratory";
}

function printReport(report) {
  console.log("");
  console.log(`Frame Conn patch corridor: ${report.goal}`);
  console.log(`${report.summary.families} families | ${report.summary.files} targeted files | ${report.summary.symbols} symbol anchors | ${report.summary.confidence} confidence`);
  console.log("");
  console.log("Architectural corridor:");
  console.log(`  ${report.corridor.join(" -> ")}`);
  console.log("");
  console.log("Targeted patch surface:");
  for (const file of report.files) {
    console.log(`  ${file.file} [${file.family}]`);
    for (const symbol of file.symbols.slice(0, 6)) console.log(`    L${symbol.line} ${symbol.kind} ${symbol.name}`);
  }
  console.log("");
  console.log("Runtime convergence:");
  for (const item of report.runtime) console.log(`  ${item.river}: ${item.convergence ?? "composition"}${item.outlet ? ` -> ${item.outlet}` : ""}`);
  console.log("");
  console.log("Effect boundary candidates:");
  if (report.effects.length === 0) console.log("  no effect-producing family required by current corridor");
  for (const owner of report.effects) console.log(`  ${owner.id}: ${owner.siteCount ?? 0} effect sites | ${owner.status ?? "healthy"}`);
  console.log("");
  console.log(`Expected scope: <= ${report.scope.maxFilesSuggested} files, ${report.scope.familyCount} families, ${report.scope.symbolAnchorCount} strong symbol anchors`);
  console.log(`Report: ${outputFile}`);
}

function main() {
  console.log("Frame Conn patch corridor planner starting...");
  console.log(`Goal: ${goal}`);

  const repoReport = runDiagnostic("repo-audit.mjs", "frame-conn-corridor-repo");
  const symbolReport = runDiagnostic("symbol-family-audit.mjs", "frame-conn-corridor-symbols");
  const effectReport = runDiagnostic("effect-atlas.mjs", "frame-conn-corridor-effects");

  const { graph, familyMap, flow } = familyGraphFromReports(symbolReport, repoReport);
  const rankedFamilies = [...familyMap.values()]
    .map(family => ({ id: family.id, score: familyScore(family, effectReport) }))
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));

  const corridor = deriveCorridor(graph, rankedFamilies);
  const files = inspectCandidateFiles(corridor, familyMap, rankedFamilies);
  const runtime = runtimeConvergence(flow, corridor);
  const effects = effectBoundary(effectReport, corridor);
  const symbolAnchorCount = files.reduce((sum, file) => sum + file.symbols.length, 0);

  const report = {
    planner: { name: "Frame Conn Patch Corridor Planner", scriptVersion: SCRIPT_VERSION, generatedAt: new Date().toISOString() },
    goal,
    goalTokens,
    summary: { families: corridor.length, files: files.length, symbols: symbolAnchorCount, confidence: confidence(files, rankedFamilies) },
    corridor,
    rankedFamilies: rankedFamilies.slice(0, 12),
    files,
    runtime,
    effects,
    scope: {
      familyCount: corridor.length,
      symbolAnchorCount,
      maxFilesSuggested: Math.max(1, Math.min(14, files.length)),
      certificationRule: "Prefer edits inside this corridor; any file outside it should be justified by a newly discovered dependency, runtime binding, or effect boundary."
    },
    diagnosticBaseline: {
      dependencyErrors: repoReport.summary?.errors ?? null,
      symbolErrors: symbolReport.summary?.errors ?? null,
      effectErrors: effectReport.summary?.errors ?? null,
      effectWarnings: effectReport.summary?.warnings ?? null
    }
  };

  fs.writeFileSync(outputFile, `${JSON.stringify(report, null, 2)}\n`, "utf8");
  printReport(report);
}

try {
  main();
} catch (error) {
  console.error(`[patch-corridor] ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}
